// HasRedeemerWith applies the HasEdge predicate on the "redeemer" edge with a given conditions (other predicates).
func HasRedeemerWith(preds ...predicate.User) predicate.GiftCode {
	return predicate.GiftCode(func(s *sql.Selector) {
		step := newRedeemerStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

